draw(Circle((2,0),1));
draw(Circle((-2,0),1));
draw((-2,0)--(2,0));
draw(Circle((0,1.5),1.5),dotted);
draw(Circle((0,0),3));
dot((-2,0) ^^ (2,0) ^^ (0,0) ^^ (0,1.5));
