unitsize(3 cm);

pair A, B, C, M, N, O;

O = (0,0);
A = dir(140);
B = dir(200);
C = dir(-20);
M = (B + C)/2;
N = (A + C)/2;

draw(A--B--C--cycle);
draw(M--O--N);

label("$A$", A, dir(90));
label("$B$", B, SW);
label("$C$", C, SE);
label("$M$", M, S);
label("$N$", N, NE);
label("$O$", O, NW);
[/asy]

[asy]
