draw(A--B--C--D--cycle);
draw(A--E--B);
draw(E--F);
dot(dots);
label("A",A,SW);
label("B",B,SE);
label("C",C,NE);
label("D",D,NW);
label("E",E,N);
label("F",F,S);
[/asy]

