draw((0,0)--V,red,Arrow(6));
draw((0,0)--R,blue,Arrow(6));
draw((0,0)--P,green,Arrow(6));
draw(V--R,dashed);

label("$\mathbf{v} = \begin{pmatrix} -2 \\ 3 \end{pmatrix}$", V, N);
label("$\begin{pmatrix} 2 \\ 1 \end{pmatrix}$", D, E);
label("$\mathbf{r}$", R, SE);
label("$\mathbf{p}$", P, S);
[/asy]

We can compute that
\begin{align*}
\mathbf{p} &= \operatorname{proj}_{\begin{pmatrix} 2 \\ 1 \end{pmatrix}} \begin{pmatrix} -2 \\ 3 \end{pmatrix} \\
&= \frac{\begin{pmatrix} -2 \\ 3 \end{pmatrix} \cdot \begin{pmatrix} 2 \\ 1 \end{pmatrix}}{\begin{pmatrix} 2 \\ 1 \end{pmatrix} \cdot \begin{pmatrix} 2 \\ 1 \end{pmatrix}} \begin{pmatrix} 2 \\ 1 \end{pmatrix} \\
&= \frac{-1}{5} \begin{pmatrix} 2 \\ 1 \end{pmatrix} \\
&= \begin{pmatrix} -\frac{2}{5} \\ -\frac{1}{5} \end{pmatrix}.
\end{align*}Since $\mathbf{p}$ is the midpoint of $\mathbf{v}$ and $\mathbf{r},$ $\mathbf{p} = \frac{\begin{pmatrix} -2 \\ 3 \end{pmatrix} + \mathbf{r}}{2},$ so
\[\mathbf{r} = 2 \mathbf{p} - \mathbf{v} = 2 \begin{pmatrix} -\frac{2}{5} \\ -\frac{1}{5} \end{pmatrix} - \begin{pmatrix} -2 \\ 3 \end{pmatrix} = \boxed{\begin{pmatrix} 6/5 \\ -17/5 \end{pmatrix}}.\]

We plot $r = 1 + \cos \theta.$  If we rotate it around the point $(2,0),$ then the curve sweeps out a circle of radius $R,$ where $R$ is the maximum distance between a point on the curve and the point $(2,0).$

[asy]
unitsize(1 cm);

pair moo (real t) {
  real r = 1 + cos(t);
  return (r*cos(t), r*sin(t));
}

path foo = moo(0);
real t;

for (t = 0; t <= 2*pi + 0.1; t = t + 0.1) {
  foo = foo--moo(t);
}

filldraw(Circle((2,0),4/sqrt(3)),gray(0.9),gray(0.9));
draw(foo);

dot((2,0), red);
label("$(2,0)$", (2,0), E);
